<template><main class="page"><header><div><p class="eyebrow">STAGE 28 GLOBAL COMMONS</p><h1>全球认知公地</h1><p>去中心化证明、因果公共信号、自治财政与文明安全阀。</p></div><el-button :icon="Refresh" circle title="刷新" :loading="loading" @click="load"/></header><section class="metrics"><div v-for="m in metrics" :key="m.key"><span>{{m.label}}</span><strong>{{overview[m.key]??0}}</strong></div></section><el-tabs v-model="tab"><el-tab-pane label="共识与治理" name="govern"><section class="grid"><article v-for="x in cards" :key="x.title"><el-icon><component :is="x.icon"/></el-icon><h2>{{x.title}}</h2><p>{{x.text}}</p><el-tag :type="x.type" effect="plain">{{x.state}}</el-tag></article></section></el-tab-pane><el-tab-pane label="四节点共识" name="consensus"><section class="form"><h2>运行拜占庭容错验证</h2><p>四个节点允许一个恶意节点，至少三个有效签名形成提交。</p><el-button type="primary" :icon="Connection" @click="runConsensus">运行共识</el-button><div v-if="decision" class="result"><span>共识结果</span><strong>{{decision}}</strong></div></section></el-tab-pane><el-tab-pane label="长期安全" name="safety"><section class="grid"><article><el-icon><TrendCharts/></el-icon><h2>百年风险</h2><p>AI、气候、生物安全、能源和地缘风险十年步长联合模拟。</p></article><article><el-icon><SwitchButton/></el-icon><h2>文明安全阀</h2><p>多方暂停、离线降级、能力上限和受控恢复。</p></article><article><el-icon><Box/></el-icon><h2>主权发行网络</h2><p>分层镜像、离线补丁、节点证明和联邦兼容认证。</p></article></section></el-tab-pane></el-tabs></main></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref}from'vue';import{Box,Coin,Connection,DocumentChecked,Refresh,SwitchButton,TrendCharts}from'@element-plus/icons-vue';import{ElMessage}from'element-plus';import{cognitiveCommonsApi}from'@/api/cognitiveCommons';const loading=ref(false),tab=ref('govern'),decision=ref(''),overview=reactive<Record<string,number>>({});const metrics=computed(()=>[{key:'consensus',label:'共识轮次'},{key:'constitutions',label:'联邦宪法'},{key:'preservations',label:'证据保鲜'},{key:'causal_signals',label:'因果信号'},{key:'dissent_markets',label:'反共识市场'},{key:'treasuries',label:'公共国库'},{key:'appeals',label:'配给申诉'},{key:'century_scenarios',label:'百年情景'},{key:'safety_valves',label:'安全阀'},{key:'releases',label:'主权发行'}]),cards=[{title:'证明共识层',text:'四节点在一个恶意节点存在时仍确定性提交证明状态。',state:'BFT 门禁',type:'success',icon:Connection},{title:'联邦宪法协议',text:'所有参与方均允许且固化条款不受损才可跨域行动。',state:'共同允许',type:'danger',icon:DocumentChecked},{title:'自治公共财政',text:'收入、拨款、支出、准备金与期末余额严格守恒。',state:'可验证国库',type:'warning',icon:Coin}];async function load(){loading.value=true;try{Object.assign(overview,await cognitiveCommonsApi.overview())}finally{loading.value=false}}async function runConsensus(){try{const nodes=['a','b','c','d'],votes=nodes.map((node,i)=>({node,decision:i===3?'revoked':'available',signature_valid:true}));const r=await cognitiveCommonsApi.consensus({proof_id:'demo',nodes,votes,fault_tolerance:1});decision.value=`${r.status}: ${r.decision}`;ElMessage.success('共识验证完成');await load()}catch{ElMessage.error('共识验证失败')}}onMounted(load)</script>
<style scoped>.page{max-width:1260px;margin:auto;padding:28px 24px 48px}.page header{display:flex;justify-content:space-between;gap:24px;border-bottom:1px solid var(--el-border-color);padding-bottom:20px}.page h1{font-size:30px;margin:4px 0 6px;letter-spacing:0}.page header p{margin:0;color:var(--el-text-color-secondary)}.eyebrow{font-size:12px!important;color:var(--el-color-primary)!important;font-weight:700}.metrics{display:grid;grid-template-columns:repeat(10,1fr);margin-bottom:22px}.metrics>div{padding:16px 10px;border-bottom:1px solid var(--el-border-color);border-right:1px solid var(--el-border-color)}.metrics span{display:block;font-size:11px;color:var(--el-text-color-secondary)}.metrics strong{font-size:22px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--el-border-color);border:1px solid var(--el-border-color)}.grid article{background:var(--el-bg-color);padding:24px;min-height:185px}.grid .el-icon{font-size:25px;color:var(--el-color-primary)}.grid h2,.form h2{font-size:17px}.grid p,.form p{color:var(--el-text-color-secondary);line-height:1.6}.form{padding:16px 0}.result{margin-top:24px;border-block:1px solid var(--el-border-color);padding:18px 0}.result span{display:block;color:var(--el-text-color-secondary)}.result strong{font-size:28px}@media(max-width:900px){.metrics{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.page{padding:18px 14px}.page h1{font-size:25px}}</style>
